    x_oracle.update_price<USDC>(&clock, oracle_t::calc_scaled_price(999, 3)); // $0.999
    x_oracle.update_price<USDT>( &clock, oracle_t::calc_scaled_price(998, 3)); // $0.998
    x_oracle.update_price<ETH>( &clock, oracle_t::calc_scaled_price(600, 0)); // $600

